solution.code:
function countdown(n) {
  if (n <= 0) return; // base case stops the recursion
  console.log(n);
  countdown(n - 1);
}

countdown(3); // logs 3, 2, 1 then stops

function deepSum(arr) {
  let total = 0;
  for (const item of arr) {
    if (Array.isArray(item)) {
      total += deepSum(item);
    } else {
      total += item;
    }
  }
  return total;
}

console.log(deepSum([1, [2, 3], [4, [5, 6]]])); // 21
